namespace sv_f1562b04d1d142e6989d3e0be27fcbfd.Services;

/// <summary>
/// Scoped service (per-circuit) that holds the currently selected warehouse
/// and notifies all subscribed components when the selection changes.
/// </summary>
public class WarehouseStateService
{
    private string _currentWarehouseId = "WH-001";

    public string CurrentWarehouseId
    {
        get => _currentWarehouseId;
        set
        {
            if (_currentWarehouseId != value)
            {
                _currentWarehouseId = value;
                NotifyStateChanged();
            }
        }
    }

    public string CurrentWarehouseName =>
        Warehouses.FirstOrDefault(w => w.Id == _currentWarehouseId)?.Name ?? "Unknown";

    public IReadOnlyList<Warehouse> Warehouses { get; } = new List<Warehouse>
    {
        new("WH-001", "Warehouse A - Downtown"),
        new("WH-002", "Warehouse B - Airport"),
        new("WH-003", "Warehouse C - Harbor"),
        new("WH-004", "Warehouse D - Industrial Park")
    };

    public event Action? OnChange;

    private void NotifyStateChanged() => OnChange?.Invoke();
}

public record Warehouse(string Id, string Name);

namespace sv_f1562b04d1d142e6989d3e0be27fcbfd.Services;

/// <summary>
/// Scoped service (per-circuit) that polls for low-stock inventory alerts
/// and notifies all subscribed components when new data arrives.
/// </summary>
public class InventoryAlertService : IDisposable
{
    private readonly WarehouseStateService _warehouseState;
    private readonly Random _random = new();
    private Timer? _pollingTimer;
    private int _subscriberCount;
    private int _currentAlertCount;

    public InventoryAlertService(WarehouseStateService warehouseState)
    {
        _warehouseState = warehouseState;
        _warehouseState.OnChange += HandleWarehouseChanged;
    }

    public int CurrentAlertCount => _currentAlertCount;

    /// <summary>
    /// Fired when alert data changes. All subscribed components receive this.
    /// </summary>
    public event Action? OnAlertCountChanged;

    /// <summary>
    /// Simulates a database query returning the count of items below minimum stock levels.
    /// </summary>
    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        return Task.FromResult(_random.Next(0, 16));
    }

    /// <summary>
    /// Called by components to start polling. Uses reference counting so polling
    /// runs as long as at least one component is subscribed.
    /// </summary>
    public void StartPolling()
    {
        _subscriberCount++;
        if (_subscriberCount == 1)
        {
            _pollingTimer = new Timer(PollCallback, null, TimeSpan.Zero, TimeSpan.FromSeconds(10));
        }
    }

    /// <summary>
    /// Called by components to stop polling when they are disposed.
    /// </summary>
    public void StopPolling()
    {
        _subscriberCount = Math.Max(0, _subscriberCount - 1);
        if (_subscriberCount == 0)
        {
            _pollingTimer?.Dispose();
            _pollingTimer = null;
        }
    }

    private async void PollCallback(object? state)
    {
        try
        {
            var count = await GetLowStockCountAsync(_warehouseState.CurrentWarehouseId);
            _currentAlertCount = count;
            OnAlertCountChanged?.Invoke();
        }
        catch
        {
            // Swallow exceptions during polling to avoid crashing the circuit
        }
    }

    private async void HandleWarehouseChanged()
    {
        if (_pollingTimer is not null)
        {
            // Immediately refresh when warehouse changes
            var count = await GetLowStockCountAsync(_warehouseState.CurrentWarehouseId);
            _currentAlertCount = count;
            OnAlertCountChanged?.Invoke();
        }
    }

    public void Dispose()
    {
        _warehouseState.OnChange -= HandleWarehouseChanged;
        _pollingTimer?.Dispose();
    }
}

