@page "/dashboard"
@using sv_f1562b04d1d142e6989d3e0be27fcbfd.Services
@rendermode InteractiveServer
@inject WarehouseStateService WarehouseState
@inject InventoryAlertService AlertService
@implements IDisposable

<PageTitle>Dashboard - @WarehouseState.CurrentWarehouseName</PageTitle>

<h1>Warehouse Dashboard</h1>

<div class="row mt-4">
    <div class="col-md-4">
        <div class="card">
            <div class="card-body text-center">
                <h5 class="card-title">Current Site</h5>
                <p class="card-text fs-4 fw-bold text-primary">@WarehouseState.CurrentWarehouseName</p>
                <p class="text-muted">ID: @WarehouseState.CurrentWarehouseId</p>
            </div>
        </div>
    </div>

    <div class="col-md-4">
        <div class="card @(_alertCount > 5 ? "border-danger" : _alertCount > 0 ? "border-warning" : "border-success")">
            <div class="card-body text-center">
                <h5 class="card-title">Low Stock Alerts</h5>
                <p class="card-text fs-1 fw-bold @(_alertCount > 5 ? "text-danger" : _alertCount > 0 ? "text-warning" : "text-success")">
                    @_alertCount
                </p>
                <p class="text-muted">Items below minimum level</p>
            </div>
        </div>
    </div>

    <div class="col-md-4">
        <div class="card">
            <div class="card-body text-center">
                <h5 class="card-title">Polling Status</h5>
                <p class="card-text">
                    <span class="badge bg-success">● Active</span>
                </p>
                <p class="text-muted">Refreshing every 10 seconds</p>
            </div>
        </div>
    </div>
</div>

<div class="mt-4">
    <p class="text-muted fst-italic">
        Last updated: @_lastUpdated.ToString("HH:mm:ss")
    </p>
</div>

@code {
    private int _alertCount;
    private DateTime _lastUpdated = DateTime.Now;

    protected override void OnInitialized()
    {
        _alertCount = AlertService.CurrentAlertCount;
        AlertService.OnAlertCountChanged += HandleAlertCountChanged;
        WarehouseState.OnChange += HandleWarehouseChanged;

        // Start polling when dashboard is visible
        AlertService.StartPolling();
    }

    private void HandleAlertCountChanged()
    {
        InvokeAsync(() =>
        {
            _alertCount = AlertService.CurrentAlertCount;
            _lastUpdated = DateTime.Now;
            StateHasChanged();
        });
    }

    private void HandleWarehouseChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        // Stop polling when user leaves the page
        AlertService.StopPolling();
        AlertService.OnAlertCountChanged -= HandleAlertCountChanged;
        WarehouseState.OnChange -= HandleWarehouseChanged;
    }
}

